.page {
  --cw-navy: #071a2d;
  --cw-aqua: #16dde3;
  --cw-ink: #10263a;
  --cw-muted: #637482;
  --cw-line: #d8e1e7;
  --cw-bg: #f4f8fb;
  min-width: 0;
  min-height: 100vh;
  max-width: none;
  margin: 0;
  padding: clamp(0.75rem, 2vw, 2rem);
  background: var(--cw-bg);
  color: var(--cw-ink);
}

.header {
  display: flex;
  max-width: 92rem;
  margin: 0 auto 1rem;
  padding: clamp(1rem, 3vw, 2rem);
  gap: 1rem;
  align-items: flex-start;
  justify-content: space-between;
  border-radius: 1rem;
  background: var(--cw-navy);
  color: white;
}

.header h1 {
  max-width: 52rem;
  margin: 0.15rem 0 0.45rem;
  font-size: clamp(1.55rem, 4vw, 2.8rem);
  line-height: 1.08;
}

.eyebrow {
  margin: 0;
  color: var(--cw-aqua);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.lede {
  max-width: 55rem;
  margin: 0;
  color: #c9d8e2;
}

.pending {
  flex: 0 0 auto;
  padding: 0.55rem 0.75rem;
  border: 1px solid #47657b;
  border-radius: 999px;
  color: #e3edf2;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  max-width: 92rem;
  margin: 0 auto;
  gap: 1rem;
}

.card,
.checklist {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--cw-line);
  border-radius: 1rem;
  background: white;
  box-shadow: 0 0.3rem 1.3rem rgb(7 26 45 / 5%);
}

.cardHead {
  display: flex;
  min-width: 0;
  padding: 0.8rem 1rem;
  gap: 0.8rem;
  align-items: center;
