.markGrid,
.iconGrid,
.appGrid {
  display: grid;
  padding: 1rem;
  gap: 0.9rem;
}

.markGrid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.iconGrid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.appGrid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.card figure {
  min-width: 0;
  margin: 0;
  text-align: center;
}

.card figure figcaption {
  margin-top: 0.45rem;
  color: var(--cw-muted);
  font-size: 0.75rem;
