  object-fit: contain;
}

.faviconCell {
  display: grid;
  min-height: 5rem;
  place-items: center;
}

.appGrid img {
  display: block;
  width: 100%;
  max-width: 8rem;
  aspect-ratio: 1;
  margin: 0 auto;
  border-radius: 22%;
  object-fit: contain;
  box-shadow: 0 0.45rem 1rem rgb(7 26 45 / 16%);
}

.maskStage {
  display: grid;
  min-height: 18rem;
  place-items: center;
  padding: 1.25rem;
  background:
    linear-gradient(45deg, #eef4f7 25%, transparent 25%) 0 0 / 1rem 1rem,
    linear-gradient(-45deg, #eef4f7 25%, transparent 25%) 0 0 / 1rem 1rem,
    linear-gradient(45deg, transparent 75%, #eef4f7 75%) 0 0 / 1rem 1rem,
    linear-gradient(-45deg, transparent 75%, #eef4f7 75%) 0 0 / 1rem 1rem;
}

.safeCircle {
  width: min(15rem, 72vw);
  aspect-ratio: 1;
  overflow: hidden;
  border: 2px dashed #f19b38;
  border-radius: 50%;
}

.safeCircle img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.wide {
  grid-column: 1 / -1;
}

.socialGrid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(0, 0.7fr);
  padding: 1rem;
  gap: 1rem;
  align-items: start;
}

.mediaFrameWide,
.mediaFrameSquare {
  width: 100%;
  overflow: hidden;
  border-radius: 0.75rem;
  background: var(--cw-navy);
}

.mediaFrameWide {
