}

.checklist ul {
  columns: 2;
  margin-bottom: 0;
  padding-left: 1.2rem;
  gap: 2rem;
}

.checklist li {
  break-inside: avoid;
  margin-bottom: 0.6rem;
}

@media (max-width: 760px) {
