      })
      .then((payload) => {
        setHeroExperience(payload);
        setHeroState("ready");
      })
      .catch(() => {
        if (!controller.signal.aborted) setHeroState("error");
      });
    return () => controller.abort();
  }, [hero]);

  if (!initialHome) {
    return (
      <section className={styles.unavailable}>

      .catch(() => { setGenres([]); setState("error"); });
  }
  useIntersectionStart(ref, state !== "idle", load);
  if (state === "empty") return null;
  return <section ref={ref} className={styles.section}>{state === "ready" ? <><SectionHeading title="Genres" destination="/genres" /><div className={styles.genreGrid}>{genres.map((genre) => <Link key={genre.slug} href={genre.future_path}><span>{genre.name}</span></Link>)}</div></> : null}{state === "idle" || state === "loading" ? <RailSkeleton /> : null}{state === "error" ? <RailFailure label="genres" onRetry={load} /> : null}</section>;
}

function LazyTrailerRail() {
  const ref = useRef<HTMLElement | null>(null);
  const [payload, setPayload] = useState<HomeTrailerRailResponse | null>(null);
  const [state, setState] = useState<RemoteState>("idle");
  function load() {
    setState("loading");
    fetch("/api/cinewatch/home/trailers", { cache: "no-store" })
      .then(async (response) => { if (!response.ok) throw new Error(`trailers ${response.status}`); return await response.json() as HomeTrailerRailResponse; })
      .then((value) => { setPayload(value); setState(value.items?.length ? "ready" : "empty"); })
      .catch(() => { setPayload(null); setState("error"); });
  }
  useIntersectionStart(ref, state !== "idle", load);
  if (state === "empty") return null;
  return (
    <section ref={ref} className={styles.section}>
      {state === "ready" && payload ? <><SectionHeading title={payload.title} /><div className={styles.trailerRail}>{(payload.items ?? []).map(({ item, trailer }) => { const art = item.backdrop_url ?? item.poster_url; return <Link key={`${item.media_type}-${item.provider_id}-${trailer.youtube_key}`} href={`/title/${item.media_type}/${item.provider_id}/trailers`} className={styles.trailerCard}>{art ? <img src={art} alt="" loading="lazy" /> : null}<span className={styles.playDisc}>▶</span><strong>{item.title}</strong><small>YouTube · {trailer.video_type}</small></Link>; })}</div></> : null}
      {state === "idle" || state === "loading" ? <RailSkeleton /> : null}
      {state === "error" ? <RailFailure label="trailers" onRetry={load} /> : null}
    </section>
  );
}

function RailFailure({ label, onRetry }: { label: string; onRetry: () => void }) {
  return <div className={styles.railError}><strong>{label.charAt(0).toUpperCase() + label.slice(1)} could not be loaded.</strong><span>Try again in a moment.</span><button type="button" onClick={onRetry}>Retry</button></div>;
}

function RailSkeleton() {
  return <div className={styles.skeletonWrap} aria-label="Loading section"><div className={styles.skeletonTitle} /><div className={styles.skeletonRail}>{Array.from({ length: 6 }, (_, index) => <span key={index} />)}</div></div>;
}

"use client";
/* eslint-disable @next/next/no-img-element */

import { useEffect, useState } from "react";

import styles from "./RelatedNews.module.css";

type Article = {
  source: { name: string };
  title: string;
  description: string | null;
  article_url: string;
  image_url: string | null;
  published_at: string | null;
};

type NewsResponse = { articles: Article[] };
type State = "loading" | "ready" | "empty" | "error";

export default function RelatedNews({ query, heading = "In the News" }: { query: string; heading?: string }) {
  const [state, setState] = useState<State>("loading");
  const [articles, setArticles] = useState<Article[]>([]);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    const controller = new AbortController();
    const startTimer = window.setTimeout(() => {
      setState("loading");
      const params = new URLSearchParams({ q: query, page_size: "3" });
      fetch(`/api/cinewatch/news?${params.toString()}`, { cache: "no-store", signal: controller.signal, headers: { Accept: "application/json" } })
        .then(async (response) => {
          if (!response.ok) throw new Error(`news ${response.status}`);
          return await response.json() as NewsResponse;
        })
        .then((payload) => {
          const next = payload.articles ?? [];
          setArticles(next);
          setState(next.length ? "ready" : "empty");
        })
        .catch(() => {
          if (!controller.signal.aborted) {
            setArticles([]);
            setState("error");
          }
        });
    }, 0);
    return () => {
      window.clearTimeout(startTimer);
      controller.abort();
    };
  }, [query, attempt]);

  if (state === "empty") return null;
  return (
    <section className={styles.section}>
      <div className={styles.head}><div><p>CineWatch News</p><h2>{heading}</h2></div><a href={`/news?q=${encodeURIComponent(query)}`}>More news →</a></div>
      {state === "loading" ? <p className={styles.muted}>Loading live news…</p> : null}
      {state === "error" ? <div className={styles.failure}><strong>News could not be loaded.</strong><span>Try again in a moment.</span><button type="button" onClick={() => setAttempt((value) => value + 1)}>Retry</button></div> : null}
      {state === "ready" ? <div className={styles.grid}>{articles.map((article) => <a key={article.article_url} href={article.article_url} target="_blank" rel="noopener noreferrer">{article.image_url ? <img src={article.image_url} alt="" loading="lazy" /> : null}<div><small>{article.source.name}{article.published_at ? ` · ${article.published_at.slice(0, 10)}` : ""}</small><strong>{article.title}</strong>{article.description ? <p>{article.description}</p> : null}</div></a>)}</div> : null}
    </section>
  );
}

