ok("deterministic coordinate-system contract")

optical = payload.get("optical_frame", {})
expected_optical = {
    "geometric_frame_center": [512, 512],
    "mark_center": [524, 512],
    "optical_offset": [12, 0],
    "outer_radius": 420,
    "inner_radius": 228,
    "ring_thickness": 192,
