@staticmethod
def _round_robin(groups: list[list[CatalogMediaSummary]]) -> list[CatalogMediaSummary]:
    result: list[CatalogMediaSummary] = []
    index = 0
    while True:
        added = False
        for group in groups:
            if index < len(group):
                result.append(group[index])
                added = True
        if not added:
            break
        index += 1
    return result

