    async def where_to_watch(
        self, media_type: str, tmdb_id: int, *, region: str = "US"
    ) -> ExternalAvailabilityResponse:
        if media_type not in {"movie", "tv"}:
            raise ValueError("media_type must be movie or tv")
        if tmdb_id <= 0:
