                {"with_origin_country": "NG", "sort_by": "popularity.desc", "page": 1},
            ),
        ),
    )
elif slug == "chinese":
    items = await self._combined_rail(

    requests: tuple[
        tuple[str, str, dict[str, str | int | float | bool]], ...
    ],
) -> list[HomeItem]:
    payloads = await asyncio.gather(
        *(self._tmdb.get_json(path, params=params) for path, _media_type, params in requests)
    )
    items: list[HomeItem] = []
    for payload, (_path, media_type, _params) in zip(payloads, requests, strict=True):
        items.extend(
            self._normalizer._normalize_results(
                payload,
                images=images,
                forced_media_type=media_type,
                accepted_media_types={media_type},
            )
        )

    deduped: dict[tuple[str, int], HomeItem] = {}
    for item in items:
        key = (item.media_type, item.provider_id)
        current = deduped.get(key)
        if current is None or (item.popularity or 0.0) > (current.popularity or 0.0):
            deduped[key] = item
    return sorted(
        deduped.values(),
        key=lambda item: (item.popularity or 0.0, item.provider_id),
        reverse=True,
    )[:RAIL_LIMIT]

async def _movie_trailer_card(self, item: HomeItem) -> HomeTrailerCard | None:
    payload = await self._tmdb.get_json(f"/movie/{item.provider_id}/videos", params={"language": "en-US"})
    trailer = self._select_video(self._video_results(payload))
    if trailer is None:
        return None
    return HomeTrailerCard(item=item, trailer=trailer)

async def _hero_trailer(
    self,
    details: dict[str, object],
    media_type: str,
    provider_id: int,
) -> HomeTrailer | None:
    appended_videos = details.get("videos")
    series_results = self._video_results(appended_videos if isinstance(appended_videos, dict) else {})

    if media_type == "movie":
        return self._select_video(series_results)

    latest_season, latest_air_date = self._latest_regular_season(details)
    if latest_season is not None:
        season_payload = await self._tmdb.get_json(
            f"/tv/{provider_id}/season/{latest_season}/videos",
            params={"language": "en-US"},
        )
        selected = self._select_video(
            self._video_results(season_payload),
            season_number=latest_season,
        )
        if selected is not None:
            return selected

    return self._select_video(
        series_results,
        expected_season=latest_season,
        latest_air_date=latest_air_date,
    )

async def _external_ratings(self, details: dict[str, object]) -> list[HomeExternalRating]:
    if self._omdb is None:
        return []
    external_ids = details.get("external_ids")
    if not isinstance(external_ids, dict):
        return []
    imdb_id = self._text(external_ids.get("imdb_id"))
    if not imdb_id:
        return []
    try:
        payload = await self._omdb.lookup_imdb(imdb_id)
    except ProviderError:

        return []
    return self._parse_omdb_ratings(payload)

@staticmethod
def _parse_omdb_ratings(payload: dict[str, object]) -> list[HomeExternalRating]:
    ratings: list[HomeExternalRating] = []
    raw = payload.get("Ratings")
    if isinstance(raw, list):
        for entry in raw:
            if not isinstance(entry, dict):
                continue
            source = HomepageExperienceService._text(entry.get("Source"))
            value = HomepageExperienceService._text(entry.get("Value"))
            if not source or not value:
                continue
            source_map = {
                "Internet Movie Database": "imdb",
                "Rotten Tomatoes": "rotten_tomatoes",
                "Metacritic": "metacritic",
            }
            normalized = source_map.get(source)
            if normalized:
                ratings.append(
                    HomeExternalRating(source=normalized, display_value=value)  # type: ignore[arg-type]
                )
    return ratings[:3]

@staticmethod
def _writers(details: dict[str, object], media_type: str) -> list[str]:
    names: list[str] = []
    if media_type == "tv":
        created_by = details.get("created_by")
        if isinstance(created_by, list):
            for record in created_by:
                if isinstance(record, dict):
                    name = HomepageExperienceService._text(record.get("name"))
                    if name:
                        names.append(name)

    credits = details.get("credits")
    if isinstance(credits, dict):
        crew = credits.get("crew")
        if isinstance(crew, list):
            for record in crew:
                if not isinstance(record, dict):
                    continue
                department = HomepageExperienceService._text(record.get("department"))
                job = HomepageExperienceService._text(record.get("job"))
                if department != "Writing" and job not in {"Writer", "Screenplay", "Story", "Teleplay"}:
                    continue
                name = HomepageExperienceService._text(record.get("name"))
                if name:
                    names.append(name)

    return HomepageExperienceService._dedupe_text(names)[:5]

@staticmethod
def _latest_regular_season(details: dict[str, object]) -> tuple[int | None, date | None]:
    seasons = details.get("seasons")
    if not isinstance(seasons, list):
        return None, None
    candidates: list[tuple[int, date | None]] = []
    today = date.today()
    for season in seasons:
        if not isinstance(season, dict):
            continue
        number = HomepageExperienceService._positive_int(season.get("season_number"))
        if number is None:
            continue
        air_date = HomepageExperienceService._date(season.get("air_date"))
        if air_date is not None and air_date > today:
            continue
        candidates.append((number, air_date))
    if not candidates:
        return None, None
    return max(candidates, key=lambda item: item[0])

@staticmethod
def _select_video(
    videos: list[dict[str, object]],

    *,
    season_number: int | None = None,
    expected_season: int | None = None,
    latest_air_date: date | None = None,
) -> HomeTrailer | None:
    ranked: list[tuple[tuple[int, int, int, float], HomeTrailer]] = []
    season_pattern = re.compile(r"\bseason\s+(\d+)\b", re.IGNORECASE)

    for raw in videos:
        if HomepageExperienceService._text(raw.get("site")) != "YouTube":
            continue
        video_type = HomepageExperienceService._text(raw.get("type"))
        if video_type not in {"Trailer", "Teaser"}:
            continue
        key = HomepageExperienceService._text(raw.get("key"))
        name = HomepageExperienceService._text(raw.get("name"))
        if not key or not name:
            continue

        if expected_season is not None:
            season_match = season_pattern.search(name)
            if season_match and int(season_match.group(1)) != expected_season:
                continue
            if latest_air_date is not None:
                published = HomepageExperienceService._datetime(raw.get("published_at"))
                threshold = datetime.combine(
                    latest_air_date - timedelta(days=45),
                    datetime.min.time(),
                    tzinfo=timezone.utc,
                )
                if published is not None and published < threshold:
                    continue

        published = HomepageExperienceService._datetime(raw.get("published_at"))
        official = raw.get("official") is True
        score = (
            2 if video_type == "Trailer" else 1,
            1 if official else 0,
            1 if "official" in name.casefold() else 0,
            published.timestamp() if published else 0.0,
        )
        ranked.append(
            (
                score,
                HomeTrailer(
                    youtube_key=key,
                    name=name,
                    video_type=video_type,  # type: ignore[arg-type]
                    official=official,
                    published_at=published.isoformat().replace("+00:00", "Z") if published else None,
                    season_number=season_number,
                ),
            )
        )

    if not ranked:
        return None
    ranked.sort(key=lambda pair: pair[0], reverse=True)
    return ranked[0][1]

@staticmethod
def _video_results(payload: dict[str, object]) -> list[dict[str, object]]:
    results = payload.get("results")
    if not isinstance(results, list):
        return []
    return [item for item in results if isinstance(item, dict)]

@staticmethod
def _merge_genres(
    target: dict[str, dict[str, object]],
    payload: dict[str, object],
    media_type: str,
) -> None:
    genres = payload.get("genres")
    if not isinstance(genres, list):
        return
    for raw in genres:
        if not isinstance(raw, dict):
            continue
        provider_id = HomepageExperienceService._positive_int(raw.get("id"))

        name = HomepageExperienceService._text(raw.get("name"))
        if provider_id is None or not name:
            continue
        slug = HomepageExperienceService._slug(name)
        record = target.setdefault(slug, {"name": name})
        record[f"{media_type}_provider_id"] = provider_id

@staticmethod
def _future_path(item: HomeItem) -> str:
    if item.media_type == "person":
        return f"/person/{item.provider_id}"
    return f"/title/{item.media_type}/{item.provider_id}"

@staticmethod
def _dedupe_text(values: list[str]) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for value in values:
        key = value.casefold()
        if key in seen:
            continue
        seen.add(key)
        result.append(value)
    return result

@staticmethod
def _slug(value: str) -> str:
    normalized = re.sub(r"[^a-z0-9]+", "-", value.casefold()).strip("-")
    return normalized or "genre"

@staticmethod
def _positive_int(value: object) -> int | None:
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        return None
    return value

@staticmethod
def _text(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    stripped = value.strip()
    return stripped or None

@staticmethod
def _date(value: object) -> date | None:
    text = HomepageExperienceService._text(value)
    if not text:
        return None
    try:
        return date.fromisoformat(text[:10])
    except ValueError:
        return None

@staticmethod
def _datetime(value: object) -> datetime | None:
    text = HomepageExperienceService._text(value)
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc)

"""Optional PostgreSQL-backed media resolver that never removes catalog entities."""

from __future__ import annotations

from sqlalchemy.orm import Session

from cinewatch_api.contracts.catalog import (
    CatalogBrowseResponse,
    CatalogPersonResponse,
    CatalogProviderResponse,
    CatalogSeasonResponse,
    CatalogTitleResponse,
)
from cinewatch_api.contracts.home import HomeItem, HomeResponse
from cinewatch_api.contracts.search import SearchResponse
from cinewatch_api.media.fallbacks import MediaGap
from cinewatch_api.media.repository import MediaAuthorityRepository


class MediaAuthority:
    def __init__(self, session: Session) -> None:
        self._session = session
        self._repo = MediaAuthorityRepository(session)

    def _resolve(self, gap: MediaGap, provider_url: str | None) -> str | None:
        override = self._repo.find_override(gap)
        if override:
            return override
        if provider_url:
            return provider_url
        self._repo.record_gap(gap)
        return None

    def apply_home(self, payload: HomeResponse) -> HomeResponse:
        items: list[HomeItem] = []
        if payload.hero is not None:
            items.append(payload.hero)
        for group in (
            payload.sections.trending,
            payload.sections.popular_movies,
            payload.sections.popular_tv,
            payload.sections.trending_people,
        ):
            items.extend(group)
        seen: set[tuple[str, int]] = set()
        for item in items:
            key = (item.media_type, item.provider_id)
            if key in seen:
                continue
            seen.add(key)
            if item.media_type == "person":
                gap = MediaGap("tmdb", "person", item.provider_id, item.title, "profile")
                item.profile_url = self._resolve(gap, item.profile_url)
            else:
                poster = MediaGap("tmdb", item.media_type, item.provider_id, item.title, "poster")
                backdrop = MediaGap("tmdb", item.media_type, item.provider_id, item.title, "backdrop")
                item.poster_url = self._resolve(poster, item.poster_url)
                item.backdrop_url = self._resolve(backdrop, item.backdrop_url)
        self._session.commit()
        return payload

    def apply_title(self, payload: CatalogTitleResponse) -> CatalogTitleResponse:
        payload.poster_url = self._resolve(MediaGap("tmdb", payload.media_type, payload.provider_id, payload.title, "poster"), payload.poster_url)
        payload.backdrop_url = self._resolve(MediaGap("tmdb", payload.media_type, payload.provider_id, payload.title, "backdrop"), payload.backdrop_url)
        for member in [*payload.cast, *payload.crew]:
            member.profile_url = self._resolve(MediaGap("tmdb", "person", member.provider_id, member.name, "profile"), member.profile_url)
        for season in payload.seasons:
            if season.provider_id:
                season.poster_url = self._resolve(MediaGap("tmdb", "season", season.provider_id, season.name, "poster"), season.poster_url)
        for item in payload.recommendations:
            item.poster_url = self._resolve(MediaGap("tmdb", item.media_type, item.provider_id, item.title, "poster"), item.poster_url)
            item.backdrop_url = self._resolve(MediaGap("tmdb", item.media_type, item.provider_id, item.title, "backdrop"), item.backdrop_url)
        for network in payload.networks:
            if network.provider_id:
                network.logo_url = self._resolve(MediaGap("tmdb", "network", network.provider_id, network.name, "logo"), network.logo_url)
        for provider in payload.watch_providers:
            provider.logo_url = self._resolve(
                MediaGap("tmdb", "network", provider.provider_id, provider.name, "logo"),
                provider.logo_url,
            )

    self._session.commit()
    return payload

def apply_person(self, payload: CatalogPersonResponse) -> CatalogPersonResponse:
    payload.profile_url = self._resolve(MediaGap("tmdb", "person", payload.provider_id, payload.name, "profile"), payload.profile_url)
    for item in [*payload.credits, *payload.crew_credits]:
        item.poster_url = self._resolve(MediaGap("tmdb", item.media_type, item.provider_id, item.title, "poster"), item.poster_url)
        item.backdrop_url = self._resolve(MediaGap("tmdb", item.media_type, item.provider_id, item.title, "backdrop"), item.backdrop_url)
    self._session.commit()
    return payload

def apply_browse(self, payload: CatalogBrowseResponse) -> CatalogBrowseResponse:
    for item in payload.items:
        item.poster_url = self._resolve(MediaGap("tmdb", item.media_type, item.provider_id, item.title, "poster"), item.poster_url)
        item.backdrop_url = self._resolve(MediaGap("tmdb", item.media_type, item.provider_id, item.title, "backdrop"), item.backdrop_url)
    self._session.commit()
    return payload

def apply_season(self, payload: CatalogSeasonResponse) -> CatalogSeasonResponse:
    # Season identity in this response is represented by series provider ID + season number;
    # episode IDs remain exact TMDb episode identities.
    for episode in payload.episodes:
        episode.still_url = self._resolve(MediaGap("tmdb", "episode", episode.provider_id, episode.name, "still"), episode.still_url)
    self._session.commit()
    return payload

def apply_provider(self, payload: CatalogProviderResponse) -> CatalogProviderResponse:
    payload.logo_url = self._resolve(MediaGap("tmdb", "network", payload.provider_id, payload.name, "logo"), payload.logo_url)
    for item in payload.items:
        item.poster_url = self._resolve(MediaGap("tmdb", item.media_type, item.provider_id, item.title, "poster"), item.poster_url)
        item.backdrop_url = self._resolve(MediaGap("tmdb", item.media_type, item.provider_id, item.title, "backdrop"), item.backdrop_url)
    self._session.commit()
    return payload

def apply_search(self, payload: SearchResponse) -> SearchResponse:
    for item in payload.suggestions:
        if not item.provider_id:
            continue
        if item.entity_type == "PERSON":
            gap = MediaGap("tmdb", "person", item.provider_id, item.label, "profile")
        elif item.entity_type == "MOVIE":
            gap = MediaGap("tmdb", "movie", item.provider_id, item.label, "poster")
        elif item.entity_type == "TV_SHOW":
            gap = MediaGap("tmdb", "tv", item.provider_id, item.label, "poster")
        elif item.entity_type == "NETWORK_PROVIDER":
            gap = MediaGap("tmdb", "network", item.provider_id, item.label, "logo")
        else:
            continue
        item.image_url = self._resolve(gap, item.image_url)
    self._session.commit()
    return payload

"""Deterministic provider-media gap and fallback naming authority."""

from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass
from typing import Literal

EntityType = Literal["person", "network", "movie", "tv", "season", "episode"]
AssetKind = Literal["profile", "logo", "poster", "backdrop", "still"]
Remediation = Literal["AWAITING_HUMAN_RESEARCH", "GENERATION_ALLOWED"]

_DIRECTORY_BY_ASSET: dict[AssetKind, str] = {
    "profile": "people",
    "logo": "networks",
    "poster": "posters",
    "backdrop": "backdrops",
    "still": "episode-stills",
}

_ALLOWED: set[tuple[EntityType, AssetKind]] = {
    ("person", "profile"),
    ("network", "logo"),
    ("movie", "poster"),
    ("movie", "backdrop"),
    ("tv", "poster"),
    ("tv", "backdrop"),
    ("season", "poster"),
    ("episode", "still"),
}


def slugify(value: str) -> str:
    normalized = unicodedata.normalize("NFKD", value).encode("ascii", "ignore").decode("ascii")
    slug = re.sub(r"[^a-z0-9]+", "-", normalized.lower()).strip("-")
    return slug or "entity"


def remediation_for(asset_kind: AssetKind) -> Remediation:
    if asset_kind in {"logo", "backdrop"}:
        return "GENERATION_ALLOWED"
    return "AWAITING_HUMAN_RESEARCH"


@dataclass(frozen=True, slots=True)
class MediaGap:
    provider: str
    entity_type: EntityType
    provider_id: int
    entity_name: str
    asset_kind: AssetKind

    def __post_init__(self) -> None:
        if self.provider_id <= 0:
            raise ValueError("provider_id must be positive.")
        if (self.entity_type, self.asset_kind) not in _ALLOWED:
            raise ValueError(
                f"unsupported media gap combination: {self.entity_type}/{self.asset_kind}"
            )
        if not re.fullmatch(r"[a-z0-9]+", self.provider):
            raise ValueError("provider must be a lowercase alphanumeric code.")

    @property
    def remediation(self) -> Remediation:
        return remediation_for(self.asset_kind)

    @property
    def directory(self) -> str:
        return _DIRECTORY_BY_ASSET[self.asset_kind]

    @property
    def suggested_filename(self) -> str:
        normalized = unicodedata.normalize("NFKD", self.entity_name).encode("ascii", "ignore").decode("ascii")
        stem = re.sub(r"[^A-Za-z0-9]+", "_", normalized).strip("_") or f"entity_{self.provider_id}"
        suffix = {"profile": "profile", "logo": "logo", "poster": "poster", "backdrop": "backdrop", "still": "still"}[self.asset_kind]
        return f"{stem}_{suffix}.webp"

    @property
    def public_path(self) -> str:

    text = NewsService._text(value)
    if not text:
        return None
    parsed = urlparse(text)
    if parsed.scheme != "https" or not parsed.netloc:
        return None
    return text

@staticmethod
def _text(value: object) -> str | None:
