def _genre_suggestions(
    self,
    query: str,
    movie_payload: dict[str, object],
    tv_payload: dict[str, object],
) -> list[SearchSuggestion]:
    needle = query.casefold()
    merged: dict[str, str] = {}
    for payload in (movie_payload, tv_payload):
        values = payload.get("genres")
        if not isinstance(values, list):
            continue
        for raw in values:
            if not isinstance(raw, dict):
                continue
            name = self._text(raw.get("name"))
            if not name or needle not in name.casefold():
                continue
            slug = self._slug(name)
            merged[slug] = name
    return [
        SearchSuggestion(
            entity_type="GENRE",
            canonical_id=f"cinewatch:genre:{slug}",
            label=name,
            secondary_text="Genre",
            destination=f"/genre/{slug}",
            source="cinewatch",
        )
        for slug, name in sorted(
            merged.items(),
            key=lambda pair: (0 if pair[1].casefold().startswith(needle) else 1, pair[1].casefold()),
        )
    ]

def _provider_suggestions(
    self,
    query: str,
    configuration: dict[str, object],
    *payloads: dict[str, object],
) -> list[SearchSuggestion]:
    images = self._normalizer._image_configuration(configuration)
    needle = query.casefold()

    merged: dict[int, tuple[str, str | None]] = {}
    for payload in payloads:
        values = payload.get("results")
        if not isinstance(values, list):
            continue
        for raw in values:
            if not isinstance(raw, dict):
                continue
            provider_id = self._positive_int(raw.get("provider_id"))
            name = self._text(raw.get("provider_name"))
            if provider_id is None or not name or needle not in name.casefold():
                continue
            logo_path = self._text(raw.get("logo_path"))
            logo_url = (
                self._normalizer._image_url(images.secure_base_url, images.profile_size, logo_path)
                if logo_path
                else None
            )
            merged[provider_id] = (name, logo_url)
    rows = sorted(
        merged.items(),
        key=lambda pair: (0 if pair[1][0].casefold().startswith(needle) else 1, pair[1][0].casefold()),
    )
    return [
        SearchSuggestion(
            entity_type="NETWORK_PROVIDER",
            canonical_id=f"tmdb:watch-provider:{provider_id}",
            provider_id=provider_id,
            label=name,
            secondary_text="Streaming provider",
            image_url=logo_url,
            destination=f"/provider/{provider_id}",
            source="tmdb",
        )
        for provider_id, (name, logo_url) in rows
    ]

@staticmethod
def _year(value: str | None) -> str | None:
    if not value:
        return None
    match = re.match(r"^(\d{4})", value)
    return match.group(1) if match else None

@staticmethod
def _slug(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", value.casefold()).strip("-")

@staticmethod
def _text(value: object) -> str | None:
    if not isinstance(value, str):
        return None
    stripped = value.strip()
    return stripped or None

@staticmethod
def _positive_int(value: object) -> int | None:
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        return None
    return value

"""Private local staging for explicitly accepted NexVox WAV training samples."""

from __future__ import annotations

import base64
import binascii
import hashlib
import json
import os
from pathlib import Path

from cinewatch_api.contracts.voice import VoiceSampleStageRequest, VoiceSampleStageResponse


class VoiceStagingDisabledError(RuntimeError):
    """Raised when private staging has not been configured."""


class InvalidVoiceSampleError(ValueError):
    """Raised when a submitted sample is not a bounded RIFF/WAVE payload."""


class VoiceStagingService:
    """Persist accepted WAV + metadata with private filesystem permissions and no read API."""

    MAX_WAV_BYTES = 12 * 1024 * 1024

    def __init__(self, staging_dir: str | None) -> None:
        self._staging_dir = Path(staging_dir).expanduser() if staging_dir else None

    def stage(self, payload: VoiceSampleStageRequest) -> VoiceSampleStageResponse:
        if self._staging_dir is None:
            raise VoiceStagingDisabledError("NexVox private staging is not configured.")
        try:
            wav = base64.b64decode(payload.wav_base64, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise InvalidVoiceSampleError("Voice sample is not valid base64.") from exc
        if not wav or len(wav) > self.MAX_WAV_BYTES:
            raise InvalidVoiceSampleError("Voice sample exceeds the governed size boundary.")
        if len(wav) < 44 or wav[:4] != b"RIFF" or wav[8:12] != b"WAVE":
            raise InvalidVoiceSampleError("Voice sample must be a RIFF/WAVE file.")

        digest = hashlib.sha256(wav).hexdigest()
        sample_id = f"nexvox-{payload.metadata.tester_id}-{digest[:20]}"
        tester_dir = self._staging_dir / payload.metadata.tester_id
        tester_dir.mkdir(parents=True, exist_ok=True, mode=0o700)
        try:
            os.chmod(self._staging_dir, 0o700)
            os.chmod(tester_dir, 0o700)
        except OSError:
            pass

        wav_path = tester_dir / f"{sample_id}.wav"
        metadata_path = tester_dir / f"{sample_id}.json"
        metadata = payload.metadata.model_dump(mode="json") | {
            "sample_id": sample_id,
            "sha256": digest,
            "size_bytes": len(wav),
            "retention_status": "LOCAL_PRIVATE_STAGING",
        }

        self._write_private(wav_path, wav)
        self._write_private(
            metadata_path,
            (json.dumps(metadata, ensure_ascii=False, sort_keys=True, indent=2) + "\n").encode("utf-8"),
        )
        return VoiceSampleStageResponse(sample_id=sample_id, stored=True)

    @staticmethod
    def _write_private(path: Path, data: bytes) -> None:
        flags = os.O_WRONLY | os.O_CREAT | os.O_TRUNC
        fd = os.open(path, flags, 0o600)
        try:
            with os.fdopen(fd, "wb", closefd=False) as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
        finally:
            os.close(fd)
        try:

    os.chmod(path, 0o600)
except OSError:
    pass

